#include <bits/stdc++.h>
using namespace std;
struct E{int to,cap;};
vector<E> es; vector<vector<int>> g; vector<int> lvl,itr;
void addE(int u,int v,int c){ g[u].push_back(es.size()); es.push_back({v,c}); g[v].push_back(es.size()); es.push_back({u,0}); }
bool bfs(int s,int t){
    fill(lvl.begin(),lvl.end(),-1); queue<int> q; q.push(s); lvl[s]=0;
    while(!q.empty()){ int u=q.front(); q.pop();
        for(int id:g[u]) if(es[id].cap>0 && lvl[es[id].to]<0){ lvl[es[id].to]=lvl[u]+1; q.push(es[id].to); } }
    return lvl[t]>=0;
}
int dfs(int u,int t,int f){
    if(u==t) return f;
    for(int &i=itr[u]; i<(int)g[u].size(); i++){
        int id=g[u][i], v=es[id].to;
        if(es[id].cap>0 && lvl[v]==lvl[u]+1)
            if(int d=dfs(v,t,min(f,es[id].cap))){ es[id].cap-=d; es[id^1].cap+=d; return d; }
    }
    return 0;
}
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n,m; scanf("%d %d",&n,&m);
        int S=0, Tt=m+n+1, N=m+n+2;
        es.clear(); g.assign(N,{}); lvl.assign(N,0); itr.assign(N,0);
        for(int i=1;i<=m;i++){ int k; scanf("%d",&k); addE(S,i,1);
            for(int j=0;j<k;j++){ int f; scanf("%d",&f); addE(i,m+f,1); } }
        for(int f=1;f<=n;f++) addE(m+f,Tt,(m+1)/2);
        int flow=0;
        while(bfs(S,Tt)){ fill(itr.begin(),itr.end(),0); while(int f=dfs(S,Tt,INT_MAX)) flow+=f; }
        if(flow<m){ puts("NO"); continue; }
        vector<int> ans(m+1,0);
        for(int i=1;i<=m;i++) for(int id:g[i])
            if(id%2==0 && es[id].to>m && es[id].to<=m+n && es[id].cap==0){ ans[i]=es[id].to-m; break; }
        puts("YES");
        for(int i=1;i<=m;i++) printf("%d ",ans[i]);
        puts("");
    }
}

