int main(){
    int q; scanf("%d",&q);
    while(q--){
        int n; scanf("%d",&n);
        vector<long long> p(n);
        for(auto &v:p) scanf("%lld",&v);
        long long x,a,y,b,k; scanf("%lld %lld %lld %lld %lld",&x,&a,&y,&b,&k);
        sort(p.rbegin(),p.rend());
        vector<long long> pre(n+1,0);
        for(int i=0;i<n;i++) pre[i+1]=pre[i]+p[i];
        long long L=a/__gcd(a,b)*b;
        auto units=[&](long long t)->long long{
            long long both=t/L, ca=t/a-both, cb=t/b-both;
            vector<pair<long long,long long>> gr={{x+y,both},{x,ca},{y,cb}};
            sort(gr.begin(),gr.end(),greater<pair<long long,long long>>());
            long long s=0,pos=0;
            for(auto &pc:gr){ s+=pc.first*(pre[pos+pc.second]-pre[pos]); pos+=pc.second; }
            return s;
        };
        long long need=k*100;
        if(units(n)<need){ puts("-1"); continue; }
        int lo=1, hi=n;
        while(lo<hi){ int mid=(lo+hi)/2; if(units(mid)>=need) hi=mid; else lo=mid+1; }
        printf("%d\n",lo);
    }
}

