int main(){
    int t; scanf("%d",&t);
    while(t--){
        long long n,k,x; scanf("%lld %lld %lld",&n,&k,&x);
        vector<long long> a(n);
        for(auto &v:a) scanf("%lld",&v);
        sort(a.begin(),a.end()); a.erase(unique(a.begin(),a.end()),a.end());
        long long m=a.size();
        auto cnt=[&](long long D)->long long{
            long long c=0;
            if(a[0]-D>=0) c+=a[0]-D+1;
            for(long long i=0;i+1<m;i++){ long long l=a[i]+D, r=a[i+1]-D; if(r>=l) c+=r-l+1; }
            long long l=a[m-1]+D; if(l<=x) c+=x-l+1;
            return c;
        };
        long long l=1,h=x,best=0;
        while(l<=h){ long long mid=(l+h)/2; if(cnt(mid)>=k){ best=mid; l=mid+1; } else h=mid-1; }
        vector<long long> out;
        if(best==0){ for(long long i=0;i<k;i++) out.push_back(i); }
        else {
            auto add=[&](long long lft,long long rgt){ for(long long p=lft;p<=rgt && (long long)out.size()<k;p++) out.push_back(p); };
            long long D=best;
            if(a[0]-D>=0) add(0,a[0]-D);
            for(long long i=0;i+1<m;i++){ long long lft=a[i]+D, rgt=a[i+1]-D; if(rgt>=lft) add(lft,rgt); }
            long long lft=a[m-1]+D; if(lft<=x) add(lft,x);
        }
        for(auto v:out) printf("%lld ",v);
        printf("\n");
    }
}

