        int n,m; scanf("%d %d",&n,&m);
        vector<vector<int>> a(n, vector<int>(m));
        vector<long long> c(n,0);
        long long S=0;
        for(int i=0;i<n;i++) for(int j=0;j<m;j++){ scanf("%d",&a[i][j]); c[i]+=a[i][j]; }
