using namespace std;
int main(){
    long long n,k,s; cin>>n>>k>>s;
    if(s<k || s>k*(n-1)){ puts("NO"); return 0; }
    if(n==2){ puts("YES"); for(long long i=0;i<k;i++) printf("%d ", i%2==0?2:1); puts(""); return 0; }
    long long e=s-k, q=e/(n-2), rem=e%(n-2);
    vector<long long> out; long long cur=1;
    for(long long i=0;i<q;i++){ cur=(cur==1)?n:1; out.push_back(cur); }
    long long left=k-q;
    if(rem>0){ cur=(cur==1)?rem+2:n-rem-1; out.push_back(cur); left--; }
    long long nb=(cur<n)?cur+1:cur-1;
    for(long long i=0;i<left;i++){ out.push_back(nb); swap(nb,cur); }
    puts("YES");
    for(auto x:out) printf("%lld ",x);
    puts("");
}

