using namespace std;
vector<long long> primesOf(long long x){
    vector<long long> r;
    for(long long p=2;p*p<=x;p++) if(x%p==0){ r.push_back(p); while(x%p==0) x/=p; }
    if(x>1) r.push_back(x);
    return r;
}
int main(){
    int n; scanf("%d",&n);
    vector<long long> a(n), b(n);
    for(int i=0;i<n;i++) scanf("%lld %lld",&a[i],&b[i]);
    vector<long long> cand=primesOf(a[0]);
    for(auto p:primesOf(b[0])) cand.push_back(p);
    for(auto p:cand){
        bool ok=true;
        for(int i=0;i<n && ok;i++) if(a[i]%p!=0 && b[i]%p!=0) ok=false;
        if(ok){ printf("%lld\n",p); return 0; }
    }
