#include <bits/stdc++.h>
using namespace std;
int par[1005];
int f(int x){ return par[x]==x? x : par[x]=f(par[x]); }
int main(){
    int n,d; scanf("%d %d",&n,&d);
    vector<int> X(d), Y(d);
    for(int i=0;i<d;i++) scanf("%d %d",&X[i],&Y[i]);
    for(int i=1;i<=n;i++) par[i]=i;
    for(int i=0;i<d;i++){
        int a=f(X[i]), b=f(Y[i]);
        if(a!=b) par[a]=b;
        vector<long long> sz(n+1,0);
        for(int v=1;v<=n;v++) sz[f(v)]++;
        vector<long long> S; long long sumAll=0, inS=0;
        for(int v=1;v<=n;v++) if(f(v)==v && sz[v]>=2){ S.push_back(sz[v]); sumAll+=sz[v]-1; inS+=sz[v]; }
        sort(S.rbegin(),S.rend());
        long long B=(i+1)-sumAll;
        long long deg=S[0]-1, links=min<long long>(B,(long long)S.size()-1);
        for(long long j=1;j<=links;j++) deg+=S[j];
        long long leftover=B-links, freeP=n-inS;
        deg+=min(leftover,freeP);
        deg=min(deg,(long long)n-1);
        printf("%lld\n",deg);
    }
}
